<section class="vc-card mt-3" id="product-sustainability">
  <div class="vc-card-head"><div><h2>Materials, sustainability and end of life</h2><span class="vc-help">Use precise claims and connect every public claim to supporting evidence.</span></div><span class="vc-status warning">Evidence required</span></div>
  <div class="vc-card-body">
    <div class="vc-callout warning"><strong>Avoid greenwashing:</strong> terms such as organic, biodegradable, compostable, recycled, plastic-free, cruelty-free and carbon-neutral must be specific, measurable and supported. The future backend/admin review remains authoritative.</div>
    <div class="vc-form-grid mt-3">
      <div class="vc-field"><label for="primary-material">Primary material *</label><input class="vc-input" id="primary-material" name="primary_material" required minlength="2" maxlength="120" placeholder="e.g. GOTS-certified organic cotton"></div>
      <div class="vc-field"><label for="material-source">Material source *</label><select class="vc-select" id="material-source" name="material_source" required><option value="">Select source</option><option>Direct from producer/artisan</option><option>Local supplier within 100 km</option><option>Indian supplier</option><option>Imported supplier</option><option>Recovered/upcycled material</option><option>Mixed or multiple sources</option></select></div>
      <div class="vc-field full"><label for="other-materials">Other materials/components</label><textarea class="vc-textarea" id="other-materials" name="other_materials" maxlength="500" placeholder="List dyes, metals, adhesives, finishes, lining, thread and other components."></textarea></div>
      <div class="vc-field"><label for="craft-technique">Craft/production technique *</label><input class="vc-input" id="craft-technique" name="craft_technique" required minlength="2" maxlength="120"></div>
      
      <div class="vc-field"><label for="origin-district">Origin district</label><input class="vc-input" id="origin-district" name="origin_district" maxlength="80"></div>
      <div class="vc-field"><label for="origin-place">City/town/village or craft cluster *</label><input class="vc-input" id="origin-place" name="origin_place" required minlength="2" maxlength="100"></div>
      <div class="vc-field"><label for="handmade-share">Handmade contribution (%) *</label><input class="vc-input" id="handmade-share" name="handmade_percent" type="number" min="0" max="100" step="1" required></div>
      <div class="vc-field"><label for="recycled-content">Verified recycled content (%)</label><input class="vc-input" id="recycled-content" name="recycled_content_percent" type="number" min="0" max="100" step="0.1"></div>
      <div class="vc-field full"><label for="sustainability-claims">Public sustainability claims</label><select class="vc-select" id="sustainability-claims" name="sustainability_claims[]" multiple size="8"><option>Handmade</option><option>Locally sourced</option><option>Organic material</option><option>Recycled content</option><option>Upcycled</option><option>Plastic-free product</option><option>Biodegradable</option><option>Compostable under specified conditions</option><option>Vegan</option><option>Cruelty-free</option><option>Renewable-energy production</option><option>Low-waste production</option><option>Repairable</option><option>Reusable</option></select><span class="vc-help">Select only claims that can be supported. “Compostable” must state home or industrial conditions.</span></div>
      <div class="vc-field"><label for="claim-evidence">Supporting credential/evidence *</label><select class="vc-select" id="claim-evidence" name="claim_evidence" required><option value="">Select uploaded evidence</option><option>ART-2026-184 · Artisan certificate</option><option>GI-BP-882 · GI authorization</option><option>GOTS-IND-22014 · Material certificate</option><option>Supplier declaration · Pending review</option><option>No formal certificate — submit documented methodology</option></select></div>
      <div class="vc-field"><label for="evidence-file">Product evidence document</label><input class="vc-input" id="evidence-file" name="sustainability_evidence" type="file" accept="image/jpeg,image/png,application/pdf" data-max-bytes="5242880"></div>
      <div class="vc-field full"><label for="claim-wording">Exact customer-facing claim *</label><textarea class="vc-textarea" id="claim-wording" name="claim_wording" required minlength="20" maxlength="500" placeholder="Example: Contains 60% post-consumer recycled cotton by product weight; verified by certificate…"></textarea></div>
      <div class="vc-field"><label for="packaging-material">Packaging material *</label><input class="vc-input" id="packaging-material" name="packaging_material" required maxlength="160" placeholder="Recycled kraft paper, paper tape…"></div>
      <div class="vc-field"><label for="packaging-recycled">Packaging recycled content (%)</label><input class="vc-input" id="packaging-recycled" name="packaging_recycled_percent" type="number" min="0" max="100" step="0.1"></div>
      <div class="vc-field full"><label class="vc-check"><input name="plastic_free_packaging" type="checkbox"> Packaging is plastic-free, including tape, labels, filler and protective wrap</label><label class="vc-check mt-2"><input name="minimal_packaging" type="checkbox"> Packaging has been reduced to the minimum required for safe delivery</label></div>
      <div class="vc-field full"><label for="care-repair">Care and repair guidance *</label><textarea class="vc-textarea" id="care-repair" name="care_repair" required minlength="20" maxlength="800"></textarea></div>
      <div class="vc-field full"><label for="end-of-life">Reuse, recycling or end-of-life instructions *</label><textarea class="vc-textarea" id="end-of-life" name="end_of_life" required minlength="20" maxlength="800"></textarea></div>
    </div>
  </div>
</section>
